import{_ as e,c as r,o as t,ae as i}from"./chunks/framework.CHDT0Kbg.js";const u=JSON.parse('{"title":"プライバシーとデータ","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/privacy.md","filePath":"ja/guide/privacy.md","lastUpdated":1795170900000}'),o={name:"ja/guide/privacy.md"};function l(n,a,c,s,d,h){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="プライバシーとデータ" tabindex="-1">プライバシーとデータ <a class="header-anchor" href="#プライバシーとデータ" aria-label="Permalink to &quot;プライバシーとデータ&quot;">​</a></h1><p>Mac に残るものと、通信が必要な場合。</p><h2 id="ローカルに保存されるもの" tabindex="-1">ローカルに保存されるもの <a class="header-anchor" href="#ローカルに保存されるもの" aria-label="Permalink to &quot;ローカルに保存されるもの&quot;">​</a></h2><p>履歴、ブックマーク、開いているタブ、ダウンロード、Cookie はローカルに保存されます。アカウントもクラウド同期もありません。プライベートウィンドウ（⌘⇧N）では履歴とセッションに残りません。</p><h2 id="通信する場合" tabindex="-1">通信する場合 <a class="header-anchor" href="#通信する場合" aria-label="Permalink to &quot;通信する場合&quot;">​</a></h2><ul><li>あなたが開くウェブサイトを読み込むとき。</li><li>広告ブロックの購読を有効にしているときの更新。失敗しても保存済みのルールは働き続けます。</li><li>あなたが指定したスクリプトやファイルをダウンロードするとき。</li></ul><h2 id="権限" tabindex="-1">権限 <a class="header-anchor" href="#権限" aria-label="Permalink to &quot;権限&quot;">​</a></h2><p>カメラとマイクの許可はサイトごとに記憶されます。位置情報と通知は macOS が管理します。ポップアップは許可したサイトだけに限定されます。</p><h2 id="ファイルアクセス" tabindex="-1">ファイルアクセス <a class="header-anchor" href="#ファイルアクセス" aria-label="Permalink to &quot;ファイルアクセス&quot;">​</a></h2><p>Persim が読めるのは、ファイルダイアログで選んだ、または明示的に許可したフォルダーだけです。設定で確認と取り消しができます。</p><h2 id="お問い合わせ" tabindex="-1">お問い合わせ <a class="header-anchor" href="#お問い合わせ" aria-label="Permalink to &quot;お問い合わせ&quot;">​</a></h2><p>プライバシーについて：<strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>。</p>',12)])])}const m=e(o,[["render",l]]);export{u as __pageData,m as default};
